package org.apache.commons.lang3;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Lang_5_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        try {
            LocaleUtils.toLocale("_EN");
            fail("Expected IllegalArgumentException for invalid locale format starting with underscore");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: _EN", e.getMessage());
        }
    }
}

